import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.yo2CxoV2.js";const b=JSON.parse('{"title":"环境、命名与能力边界","description":"","frontmatter":{},"headers":[],"relativePath":"reference/compatibility.md","filePath":"reference/compatibility.md","lastUpdated":1794339637000}'),a={name:"reference/compatibility.md"};function l(i,t,c,n,h,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="环境、命名与能力边界" tabindex="-1">环境、命名与能力边界 <a class="header-anchor" href="#环境、命名与能力边界" aria-label="Permalink to &quot;环境、命名与能力边界&quot;">​</a></h1><h2 id="运行环境" tabindex="-1">运行环境 <a class="header-anchor" href="#运行环境" aria-label="Permalink to &quot;运行环境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>发行包</td><td><code>ordloom==1.0.0</code></td></tr><tr><td>核心</td><td>Python 3.9+、Django 4.2+，版本组合须满足 Django 自身要求</td></tr><tr><td>可选数据层</td><td><code>ordloom[graphql]==1.0.0</code>，Python 3.10+、Django 5.2+</td></tr><tr><td>安装产物</td><td>包含已构建前端；普通接入不需要 Node.js</td></tr><tr><td>多进程限速/观测</td><td>Web 与任务进程使用同一原子共享缓存</td></tr><tr><td>跨进程推送</td><td>配置 ASGI、Channels 和共享 channel layer</td></tr></tbody></table><h2 id="接入命名" tabindex="-1">接入命名 <a class="header-anchor" href="#接入命名" aria-label="Permalink to &quot;接入命名&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接入项</th><th>名称</th></tr></thead><tbody><tr><td>Python / Django 应用</td><td><code>ordloom</code></td></tr><tr><td>URL</td><td><code>include(&#39;ordloom.urls&#39;)</code></td></tr><tr><td>Django 设置</td><td><code>ORDLOOM_*</code></td></tr><tr><td>字段外观</td><td><code>ordloom_fields</code></td></tr><tr><td>模型字段</td><td><code>ordloom.components.fields</code> / <code>ordloom.editor.fields</code></td></tr><tr><td>管理命令</td><td><code>ordloom_*</code></td></tr><tr><td>模板与静态资源</td><td><code>ordloom/</code></td></tr><tr><td>迁移应用标签</td><td><code>ordloom</code></td></tr><tr><td>应用表</td><td><code>ordloom_*</code></td></tr><tr><td>有效权限前缀</td><td><code>ordloom.&lt;codename&gt;</code></td></tr></tbody></table><h2 id="验证范围" tabindex="-1">验证范围 <a class="header-anchor" href="#验证范围" aria-label="Permalink to &quot;验证范围&quot;">​</a></h2><p>发布检查包含后端 API 与权限、前端单元/DOM、PostgreSQL、Redis 跨进程、原生浏览器及新 wheel 安装。 隔离安装检查实际导入、迁移、表、ContentType、权限、collectstatic 和管理路由；文档检查导航、链接及代码示例语法。 这些检查不等同任意宿主插件、生产容量、真机安装或长期大屏运行均已验收。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>模型和字段权限始终由 Django 及宿主规则执行，界面隐藏不代替授权。</li><li>GraphQL 字段显式白名单；SQL 权限范围适配需要宿主提供等价规则，不自动翻译任意 Python 策略。</li><li>SQLite 与 PostgreSQL 的精确数值表现不同，详见 <a href="./../data/field-types.html">字段与精度</a>。</li><li>地图提供经纬度取点，不提供 POI 搜索；外部图片、视频和默认瓦片依赖相应服务。</li><li>上传独立于数据库事务，取消编辑不会自动删除已上传文件。</li><li>离线业务快照采用导出副本语义，无法离线复核或撤回权限，不自动同步。</li><li>维护命令由宿主调度，诊断缓存不提供实时进程心跳；在线代码执行和云函数不属于本版能力。</li></ul>',9)])])}const _=d(a,[["render",l]]);export{b as __pageData,_ as default};
